CREATE TABLE "QuoteStage" ("id" TEXT NOT NULL,"quoteItemId" TEXT NOT NULL,"sequence" INTEGER NOT NULL,"description" TEXT NOT NULL,"duration" TEXT,"completed" BOOLEAN NOT NULL DEFAULT false,CONSTRAINT "QuoteStage_pkey" PRIMARY KEY ("id"));
CREATE TABLE "MonthlyFollowUp" ("id" TEXT NOT NULL,"tenantId" TEXT NOT NULL,"projectId" TEXT NOT NULL,"month" INTEGER NOT NULL,"year" INTEGER NOT NULL,"visitDate" TIMESTAMP(3),"present" BOOLEAN NOT NULL DEFAULT false,"notes" TEXT,CONSTRAINT "MonthlyFollowUp_pkey" PRIMARY KEY ("id"));
